@charset "UTF-8";
@import url("https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=Inter:wght@400;500;600;700&display=swap");
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.sl-app {
  --ink: #2F323B;
  --paper: #FEFEFE;
  --card: #FFFFFF;
  --line: #A7CDDE;
  --line-soft: rgba(167, 205, 222, 0.45);
  --text: #2F323B;
  --muted: #585A61;
  --gold: #2972A9;
  --gold-bright: #2E9BCB;
  --gold-soft: rgba(46, 155, 203, 0.12);
  --green: #2972A9;
  --green-soft: rgba(41, 114, 169, 0.08);
  display: flex;
  height: 100vh;
  background: var(--paper);
  color: var(--text);
  font-family: "Inter", sans-serif;
}

.sidebar {
  width: 250px;
  background: var(--ink);
  color: #FEFEFE;
  display: flex;
  flex-direction: column;
}

.brand-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 22px 20px;
  border-bottom: 1px solid rgba(254, 254, 254, 0.08);
}

.brand-logo {
  width: 40px;
  height: 40px;
  display: block;
  object-fit: contain;
  border-radius: 11px;
  flex-shrink: 0;
}

.brand-text {
  display: flex;
  flex-direction: column;
}

.brand-name {
  font-family: "Playfair Display", serif;
  font-size: 15px;
  font-weight: 700;
}

.brand-tag {
  font-size: 9px;
  color: var(--gold-bright);
  text-transform: uppercase;
  letter-spacing: 0.14em;
  margin-top: 2px;
}

.nav-menu {
  list-style: none;
  padding: 12px;
  flex: 1;
  overflow-y: auto;
}

.nav-group {
  margin-bottom: 6px;
}

.nav-section-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px 6px;
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(254, 254, 254, 0.35);
  cursor: pointer;
  user-select: none;
  transition: color 0.2s;
}

.nav-section-head:hover {
  color: rgba(254, 254, 254, 0.65);
}

.nav-section-head::after {
  content: "";
  width: 7px;
  height: 7px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(45deg);
  transition: transform 0.2s;
}

.nav-group.collapsed .nav-section-head::after {
  transform: rotate(-45deg);
}

.nav-group-items {
  list-style: none;
}

.nav-group.collapsed .nav-group-items {
  display: none;
}

.nav-item {
  position: relative;
  padding: 10px 14px;
  margin-bottom: 3px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
  color: rgba(254, 254, 254, 0.6);
  transition: all 0.2s;
}

.nav-item:hover {
  background: rgba(46, 155, 203, 0.1);
  color: #FEFEFE;
}

.nav-item.active {
  background: linear-gradient(90deg, rgba(46, 155, 203, 0.2), rgba(41, 114, 169, 0.04));
  color: var(--gold-bright);
}

.nav-item.active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 22%;
  height: 56%;
  width: 3px;
  border-radius: 3px;
  background: var(--gold-bright);
}

.sidebar-footer {
  padding: 14px;
  border-top: 1px solid rgba(254, 254, 254, 0.08);
}

.logout-btn {
  width: 100%;
  padding: 10px;
  background: transparent;
  border: 1px solid rgba(167, 205, 222, 0.22);
  border-radius: 8px;
  color: rgba(254, 254, 254, 0.6);
  font-size: 12px;
  font-weight: 500;
  font-family: "Inter", sans-serif;
  cursor: pointer;
  transition: all 0.2s;
}

.logout-btn:hover {
  border-color: var(--gold-bright);
  color: var(--gold-bright);
}

.main {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 18px 28px;
  border-bottom: 1px solid var(--line);
}

.topbar-kicker {
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--gold);
}

.topbar h2 {
  font-family: "Playfair Display", serif;
  font-size: 22px;
  font-weight: 700;
  margin-top: 2px;
}

.user-chip {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 8px 14px;
}

.user-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--green);
  color: #FEFEFE;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
}

.user-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.user-info #userEmail {
  font-size: 12px;
  font-weight: 600;
}

.role-badge {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--gold-bright);
}

.content {
  flex: 1;
  padding: 26px 28px;
  overflow-y: auto;
}

/* MÓDULO ALERTAS */
.alerts-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-bottom: 22px;
}

.alerts-heading h3 {
  font-family: "Playfair Display", serif;
  font-size: 21px;
  font-weight: 700;
}

.alerts-heading p {
  color: var(--muted);
  font-size: 12px;
  margin-top: 5px;
}

.refresh-btn {
  background: var(--gold);
  color: #FFFFFF;
  border: none;
  border-radius: 9px;
  padding: 11px 16px;
  font-size: 12px;
  font-weight: 600;
  font-family: "Inter", sans-serif;
  cursor: pointer;
}

.refresh-btn:hover {
  background: var(--ink);
}

.alerts-kpi-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 22px;
}

.alerts-kpi {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 20px;
}

.alerts-kpi-label {
  display: block;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  margin-bottom: 10px;
}

.alerts-kpi-value {
  display: block;
  color: var(--gold);
  font-family: "Playfair Display", serif;
  font-size: 32px;
  font-weight: 700;
}

.alerts-panel {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 22px;
}

.alerts-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
  margin-bottom: 20px;
}

.alerts-panel-header h4 {
  font-family: "Playfair Display", serif;
  font-size: 17px;
}

.alerts-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.alert-filter {
  border: 1px solid var(--line);
  background: #FFFFFF;
  color: var(--muted);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 11px;
  font-weight: 600;
  font-family: "Inter", sans-serif;
  cursor: pointer;
}

.alert-filter.active {
  background: var(--gold);
  border-color: var(--gold);
  color: #FFFFFF;
}

.alert-card {
  border: 1px solid var(--line-soft);
  border-radius: 12px;
  padding: 18px;
  margin-bottom: 12px;
  background: #FFFFFF;
}

.alert-card.unread {
  border-left: 4px solid var(--gold-bright);
  background: rgba(167, 205, 222, 0.08);
}

.alert-card.read {
  border-left: 4px solid var(--line);
}

.alert-card-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 12px;
}

.alert-platform {
  display: inline-block;
  border-radius: 999px;
  background: var(--gold);
  color: #FFFFFF;
  padding: 5px 10px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
}

.alert-status {
  font-size: 10px;
  font-weight: 700;
  color: var(--gold);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.alert-status.read {
  color: var(--muted);
}

.alert-author {
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 8px;
}

.alert-text {
  font-size: 13px;
  line-height: 1.7;
  color: var(--text);
  overflow-wrap: anywhere;
  margin-bottom: 12px;
}

.alert-context {
  padding: 11px 13px;
  background: var(--paper);
  border: 1px solid var(--line-soft);
  border-radius: 8px;
  font-size: 11px;
  line-height: 1.6;
  color: var(--muted);
  margin-bottom: 12px;
  overflow-wrap: anywhere;
}

.alert-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  color: var(--muted);
  font-size: 10px;
}

.alert-meta a {
  color: var(--gold);
  font-weight: 600;
  text-decoration: none;
}

.alert-meta a:hover {
  text-decoration: underline;
}

.mark-read-btn {
  border: 1px solid var(--gold);
  background: #FFFFFF;
  color: var(--gold);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 11px;
  font-weight: 700;
  font-family: "Inter", sans-serif;
  cursor: pointer;
}

.mark-read-btn:hover {
  background: var(--gold-soft);
}

.mark-read-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.alert-empty {
  text-align: center;
  padding: 64px 20px;
}

.alert-empty h4 {
  font-family: "Playfair Display", serif;
  font-size: 19px;
  margin-bottom: 10px;
}

.alert-empty p {
  font-size: 12px;
  line-height: 1.7;
  color: var(--muted);
}

@media (max-width: 950px) {
  .alerts-kpi-grid {
    grid-template-columns: 1fr;
  }
  .alerts-heading {
    align-items: flex-start;
    flex-direction: column;
  }
}

