appsmith.onReady(function () {
  var navMenu = document.getElementById('navMenu');
  var alertFilter = 'all';
  var lastAlertsJson = null;
  var alertModelUnlisten = null;
  function esc(value) {
    var d = document.createElement('div');
    d.textContent = value == null ? '' : String(value);
    return d.innerHTML;
  }
  function escAttr(value) {
    return esc(value).replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }
  function parseAlerts(value) {
    if (Array.isArray(value)) {
      return value;
    }
    if (!value) {
      return [];
    }
    try {
      var parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }
  function formatDate(value) {
    if (!value) {
      return 'Fecha no disponible';
    }
    var date = new Date(value);
    if (isNaN(date.getTime())) {
      return String(value);
    }
    return date.toLocaleString('es-CR');
  }
  function safeUrl(value) {
    var url = String(value || '').trim();
    if (/^https?:\/\//i.test(url)) {
      return url;
    }
    return '';
  }
  function cleanupAlerts() {
    if (typeof alertModelUnlisten === 'function') {
      alertModelUnlisten();
      alertModelUnlisten = null;
    }
  }
  var PLAT_NAMES = {
    instagram: 'Instagram',
    tiktok: 'TikTok',
    facebook: 'Facebook',
    x: 'X (Twitter)',
    reddit: 'Reddit',
    threads: 'Threads',
    bluesky: 'Bluesky',
    snapchat: 'Snapchat',
    truth_social: 'Truth Social',
    youtube: 'YouTube',
    rumble: 'Rumble',
    twitch: 'Twitch',
    kwai: 'Kwai',
    kick: 'Kick',
    linkedin: 'LinkedIn',
    github: 'GitHub',
    telegram: 'Telegram',
    tiktok_shop: 'TikTok Shop',
    facebook_marketplace: 'FB Marketplace',
    facebook_events: 'FB Events',
    facebook_ad_library: 'FB Ad Library',
    tiktok_ad_library: 'TikTok Ad Library',
    google_ad_library: 'Google Ad Library',
    linkedin_ad_library: 'LinkedIn Ad Library',
    spotify: 'Spotify',
    apple_music: 'Apple Music',
    soundcloud: 'SoundCloud',
    google: 'Google',
    pinterest: 'Pinterest'
  };
  function platformName(code) {
    return PLAT_NAMES[code] || code || 'Plataforma';
  }
  var role = 'viewer';
  try {
    var model = appsmith.model || {};
    role = model.userRole || 'viewer';
    var email = model.userEmail || '';
    var active = model.active || 'dashboard';
    document.getElementById('userEmail').textContent = email;
    document.getElementById('userRole').textContent = role.toUpperCase();
    document.getElementById('userAvatar').textContent = email.charAt(0).toUpperCase() || 'A';
    var MENU = [{
      section: 'Análisis',
      items: [{
        id: 'dashboard',
        label: 'Dashboard',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'mentions',
        label: 'Menciones',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'analytics',
        label: 'Analítica',
        roles: ['admin', 'analyst']
      }, {
        id: 'competitors',
        label: 'Competencia',
        roles: ['admin', 'analyst']
      }]
    }, {
      section: 'Gestión',
      items: [{
        id: 'targets',
        label: 'Objetivos',
        roles: ['admin', 'analyst']
      }, {
        id: 'alerts',
        label: 'Alertas',
        roles: ['admin', 'analyst', 'viewer']
      }, {
        id: 'reports',
        label: 'Reportes',
        roles: ['admin', 'analyst', 'viewer']
      }]
    }, {
      section: 'Administración',
      items: [{
        id: 'tasks',
        label: 'Tareas de Scrapeo',
        roles: ['admin']
      }, {
        id: 'integrations',
        label: 'Integraciones',
        roles: ['admin']
      }, {
        id: 'users',
        label: 'Usuarios',
        roles: ['admin']
      }, {
        id: 'roles',
        label: 'Roles y Permisos',
        roles: ['admin']
      }, {
        id: 'audit',
        label: 'Auditoría',
        roles: ['admin']
      }, {
        id: 'settings',
        label: 'Configuración',
        roles: ['admin']
      }, {
        id: 'billing',
        label: 'Plan y Suscripción',
        roles: ['admin']
      }]
    }];
    var TITLES = {
      dashboard: 'Dashboard Ejecutivo',
      mentions: 'Menciones',
      analytics: 'Analítica',
      competitors: 'Competencia',
      targets: 'Objetivos Monitoreados',
      alerts: 'Alertas',
      reports: 'Reportes',
      tasks: 'Tareas de Scrapeo',
      integrations: 'Integraciones',
      users: 'Usuarios',
      roles: 'Roles y Permisos',
      audit: 'Auditoría',
      settings: 'Configuración',
      billing: 'Plan y Suscripción'
    };
    navMenu.innerHTML = '';
    MENU.forEach(function (section) {
      var visible = [];
      for (var i = 0; i < section.items.length; i++) {
        if (section.items[i].roles.indexOf(role) !== -1) {
          visible.push(section.items[i]);
        }
      }
      if (visible.length === 0) {
        return;
      }
      var containsActive = false;
      for (var j = 0; j < visible.length; j++) {
        if (visible[j].id === active) {
          containsActive = true;
        }
      }
      var group = document.createElement('li');
      group.className = 'nav-group' + (containsActive ? '' : ' collapsed');
      var head = document.createElement('div');
      head.className = 'nav-section-head';
      var headLabel = document.createElement('span');
      headLabel.textContent = section.section;
      head.appendChild(headLabel);
      head.addEventListener('click', function () {
        if (group.classList.contains('collapsed')) {
          group.classList.remove('collapsed');
        } else {
          group.classList.add('collapsed');
        }
      });
      group.appendChild(head);
      var list = document.createElement('ul');
      list.className = 'nav-group-items';
      visible.forEach(function (item) {
        var li = document.createElement('li');
        li.className = 'nav-item' + (item.id === active ? ' active' : '');
        li.textContent = item.label;
        li.addEventListener('click', function () {
          cleanupAlerts();
          appsmith.triggerEvent('go_' + item.id);
        });
        list.appendChild(li);
      });
      group.appendChild(list);
      navMenu.appendChild(group);
    });
    document.getElementById('viewTitle').textContent = TITLES[active] || 'Dashboard Ejecutivo';
    document.getElementById('logoutBtn').addEventListener('click', function () {
      cleanupAlerts();
      appsmith.triggerEvent('onLogout');
    });
  } catch (errShell) {
    navMenu.innerHTML = '<li style="color:#A7CDDE;padding:12px;font-size:11px;">' + 'ERROR SHELL: ' + esc(errShell.message) + '</li>';
    return;
  }
  if ((appsmith.model || {}).active === 'alerts') {
    try {
      initAlertsModule();
    } catch (errMod) {
      var area = document.getElementById('contentArea');
      if (area) {
        area.innerHTML = '<div class="alert-empty">' + '<h4>Error al cargar Alertas</h4>' + '<p>' + esc(errMod.message) + '</p>' + '</div>';
      }
    }
  }
  function renderAlerts(model) {
    var area = document.getElementById('contentArea');
    if (!area) {
      return;
    }
    model = model || {};
    lastAlertsJson = model.alertsJson;
    var alerts = parseAlerts(model.alertsJson);
    var total = alerts.length;
    var pending = alerts.filter(function (item) {
      return item.read_at == null;
    }).length;
    var read = total - pending;
    var filtered = alerts.filter(function (item) {
      if (alertFilter === 'unread') {
        return item.read_at == null;
      }
      if (alertFilter === 'read') {
        return item.read_at != null;
      }
      return true;
    });
    var cards = '';
    filtered.forEach(function (item) {
      var isUnread = item.read_at == null;
      var author = item.author_name || 'Autor no identificado';
      var comment = item.comment_text || 'Comentario sin contenido de texto.';
      var target = item.target_handle || 'Objetivo no identificado';
      var platform = platformName(item.platform);
      var postText = item.post_text || 'Publicación sin contenido de texto.';
      var url = safeUrl(item.post_url);
      var link = url ? '<a href="' + escAttr(url) + '" target="_blank" rel="noopener noreferrer">' + 'Ver publicación' + '</a>' : '';
      var button = isUnread ? '<button type="button" class="mark-read-btn" ' + 'data-read-id="' + escAttr(item.alert_id) + '">' + 'Marcar como leída' + '</button>' : '<span class="alert-status read">Leída</span>';
      cards += '<article class="alert-card ' + (isUnread ? 'unread' : 'read') + '">' + '<div class="alert-card-head">' + '<span class="alert-platform">' + esc(platform) + '</span>' + '<span class="alert-status ' + (isUnread ? '' : 'read') + '">' + (isUnread ? 'Nueva alerta' : 'Leída') + '</span>' + '</div>' + '<div class="alert-author">' + 'Nuevo comentario de ' + esc(author) + '</div>' + '<div class="alert-text">' + esc(comment) + '</div>' + '<div class="alert-context">' + '<strong>Objetivo:</strong> ' + esc(target) + '<br>' + '<strong>Publicación:</strong> ' + esc(postText) + '</div>' + '<div class="alert-meta">' + '<div>' + '<span>' + esc(formatDate(item.alert_created_at)) + '</span>' + (link ? ' · ' + link : '') + '</div>' + button + '</div>' + '</article>';
    });
    var emptyMessage = alertFilter === 'unread' ? 'No tienes alertas pendientes.' : alertFilter === 'read' ? 'Todavía no hay alertas leídas.' : 'Las alertas aparecerán cuando se detecte un comentario nuevo.';
    area.innerHTML = '<div class="alerts-heading">' + '<div>' + '<h3>Centro de alertas</h3>' + '<p>Notificaciones generadas a partir de comentarios monitoreados.</p>' + '</div>' + '<button type="button" class="refresh-btn" id="refreshAlerts">' + 'Actualizar alertas' + '</button>' + '</div>' + '<div class="alerts-kpi-grid">' + '<div class="alerts-kpi">' + '<span class="alerts-kpi-label">Total de alertas</span>' + '<span class="alerts-kpi-value">' + total + '</span>' + '</div>' + '<div class="alerts-kpi">' + '<span class="alerts-kpi-label">Pendientes</span>' + '<span class="alerts-kpi-value">' + pending + '</span>' + '</div>' + '<div class="alerts-kpi">' + '<span class="alerts-kpi-label">Leídas</span>' + '<span class="alerts-kpi-value">' + read + '</span>' + '</div>' + '</div>' + '<section class="alerts-panel">' + '<div class="alerts-panel-header">' + '<h4>Registro de notificaciones</h4>' + '<div class="alerts-filters">' + '<button type="button" class="alert-filter ' + (alertFilter === 'all' ? 'active' : '') + '" data-filter="all">' + 'Todas (' + total + ')' + '</button>' + '<button type="button" class="alert-filter ' + (alertFilter === 'unread' ? 'active' : '') + '" data-filter="unread">' + 'Pendientes (' + pending + ')' + '</button>' + '<button type="button" class="alert-filter ' + (alertFilter === 'read' ? 'active' : '') + '" data-filter="read">' + 'Leídas (' + read + ')' + '</button>' + '</div>' + '</div>' + (cards || '<div class="alert-empty">' + '<h4>Sin alertas</h4>' + '<p>' + esc(emptyMessage) + '</p>' + '</div>') + '</section>';
  }
  function initAlertsModule() {
    var area = document.getElementById('contentArea');
    renderAlerts(appsmith.model || {});
    area.addEventListener('click', function (event) {
      var filterButton = event.target.closest('button[data-filter]');
      if (filterButton) {
        alertFilter = filterButton.getAttribute('data-filter');
        renderAlerts(appsmith.model || {});
        return;
      }
      var refreshButton = event.target.closest('#refreshAlerts');
      if (refreshButton) {
        appsmith.triggerEvent('onLoadData');
        return;
      }
      var readButton = event.target.closest('button[data-read-id]');
      if (readButton) {
        var alertId = readButton.getAttribute('data-read-id');
        if (!alertId) {
          return;
        }
        readButton.disabled = true;
        appsmith.updateModel({
          selectedAlertId: alertId
        });
        setTimeout(function () {
          appsmith.triggerEvent('onMarkRead');
        }, 150);
      }
    });
    if (typeof appsmith.onModelChange === 'function') {
      alertModelUnlisten = appsmith.onModelChange(function (newModel) {
        var current = newModel || appsmith.model || {};
        if (current.alertsJson !== lastAlertsJson) {
          renderAlerts(current);
        }
      });
    }
    setTimeout(function () {
      appsmith.triggerEvent('onLoadData');
    }, 300);
  }
});

