            total +
          '</span>' +
        '</div>' +

        '<div class="alerts-kpi">' +
          '<span class="alerts-kpi-label">Pendientes</span>' +
          '<span class="alerts-kpi-value">' +
            pending +
          '</span>' +
        '</div>' +

        '<div class="alerts-kpi">' +
          '<span class="alerts-kpi-label">Leídas</span>' +
          '<span class="alerts-kpi-value">' +
            read +
          '</span>' +
        '</div>' +

      '</div>' +

      '<section class="alerts-panel">' +

        '<div class="alerts-panel-header">' +

          '<h4>Registro de notificaciones</h4>' +

          '<div class="alerts-filters">' +

            '<button type="button" class="alert-filter ' +
              (alertFilter === 'all' ? 'active' : '') +
            '" data-filter="all">' +
              'Todas (' + total + ')' +
            '</button>' +

            '<button type="button" class="alert-filter ' +
              (alertFilter === 'unread' ? 'active' : '') +
            '" data-filter="unread">' +
              'Pendientes (' + pending + ')' +
            '</button>' +

            '<button type="button" class="alert-filter ' +
              (alertFilter === 'read' ? 'active' : '') +
            '" data-filter="read">' +
              'Leídas (' + read + ')' +
            '</button>' +

          '</div>' +

        '</div>' +

        (
          cards ||
          '<div class="alert-empty">' +
            '<h4>Sin alertas</h4>' +
            '<p>' + esc(emptyMessage) + '</p>' +
          '</div>'
        ) +

      '</section>';
  }

  function initAlertsModule() {
    var area = document.getElementById('contentArea');

    renderAlerts(appsmith.model || {});

    area.addEventListener('click', function (event) {
      var filterButton = event.target.closest(
        'button[data-filter]'
      );

      if (filterButton) {
        alertFilter = filterButton.getAttribute('data-filter');

        renderAlerts(appsmith.model || {});

        return;
      }

      var refreshButton = event.target.closest(
        '#refreshAlerts'
      );

      if (refreshButton) {
        appsmith.triggerEvent('onLoadData');

        return;
      }

      var readButton = event.target.closest(
        'button[data-read-id]'
      );

      if (readButton) {
        var alertId = readButton.getAttribute('data-read-id');

        if (!alertId) {
          return;
        }

        readButton.disabled = true;

        appsmith.updateModel({
          selectedAlertId: alertId
        });

        setTimeout(function () {
          appsmith.triggerEvent('onMarkRead');
        }, 150);
      }
    });

    if (typeof appsmith.onModelChange === 'function') {
      alertModelUnlisten = appsmith.onModelChange(
        function (newModel) {
          var current = newModel || appsmith.model || {};

          if (current.alertsJson !== lastAlertsJson) {
            renderAlerts(current);
          }
        }
      );
    }

    setTimeout(function () {
      appsmith.triggerEvent('onLoadData');
    }, 300);
  }
});
